"""SQL copied from the REACH Clinical Oversight dashboard export."""

DASHBOARD_SQL = "-- Power ranking of patients by utilization metrics for each provider\n-- Identifies top 30 highest-utilization patients per provider based on composite score\n\nwith base_alignment as (\n  -- Reuse the full aco_alignment query as a base\n  with latest_month as (\n    select cast(YearNBR as int) as year, cast(MonthNBR as int) as month\n    from prd_bronze.reach_ingested.beneficiary_alignment_report_monthlydata_r2history\n    order by cast(YearNBR as int) desc, cast(MonthNBR as int) desc\n    limit 1\n  ),\n  latest_bar as (\n    select\n      b.YearNBR,\n      b.MonthNBR,\n      b.MedicareBeneficiaryID,\n      b.AlignmentStatusCD,\n      b.BirthDate,\n      b.MedicalDataSharingPreferenceFLG,\n      b.AdministrativeSuppressionFLG,\n      b.PartDPrescriptionIndicatorFLG,\n      b.SuppInsuranceFLG,\n      b.FileNM,\n      b.FileType,\n      b.FileDate,\n      b.DataSource,\n      h.hcmpi\n    from prd_bronze.reach_ingested.beneficiary_alignment_report_monthlydata_r2history b\n    cross join latest_month\n    left join prd_silver.census.hcmpimaster h\n      on h.identifier = b.MedicareBeneficiaryID\n      and h.identifiersrcfield = 'member_mbi'\n    where cast(b.YearNBR as int) = latest_month.year\n      and cast(b.MonthNBR as int) = latest_month.month\n      and b.AlignmentStatusCD = 'AL'\n  ),\n  census_data as (\n    select\n      hcmpi,\n      lc_status_current,\n      payer_current,\n      office_name,\n      first_engagement_dt,\n      latest_engagement_dt\n    from prd_silver.census.census\n    where monthyear = date_trunc('month', current_date())\n  ),\n  palmr_agg as (\n    select\n      MBI_ID,\n      array_join(collect_list(distinct ALGN_TYPE_CLM), '; ') as palmr_algn_type_clm,\n      array_join(collect_list(distinct ALGN_TYPE_VA), '; ') as palmr_algn_type_va,\n      array_join(collect_list(distinct PRVDR_TIN_NUM_CLM_OR_VA), '; ') as palmr_prvdr_tins,\n      array_join(collect_list(distinct PRVDR_NPI_NUM_CLM_OR_VA), '; ') as palmr_prvdr_npis,\n      count(*) as palmr_claim_line_count\n    from prd_bronze.reach_ingested.provider_alignment_report_r2history\n    group by MBI_ID\n  ),\n  pbvar_raw as (\n    select\n      MBI_ID,\n      ALGN_TYPE_CLM,\n      ALGN_TYPE_VA,\n      PRVDR_TIN_NUM_CLM_OR_VA,\n      PRVDR_NPI_NUM_CLM_OR_VA,\n      FileNM,\n      meta_file_dt,\n      coalesce(\n        case\n          when regexp_extract(FileNM, '\\\\.D(\\\\d)\\\\.', 1) != ''\n          then try_to_date(\n            concat(\n              '20', substr(regexp_extract(FileNM, '\\\\.D(\\\\d)\\\\.', 1), 1, 2),\n              '-',\n              substr(regexp_extract(FileNM, '\\\\.D(\\\\d)\\\\.', 1), 3, 2),\n              '-',\n              '01'\n            ),\n            'yyyy-MM-dd'\n          )\n          else null\n        end,\n        date_trunc('month', meta_file_dt)\n      ) as file_date_parsed,\n      row_number() over (\n        partition by MBI_ID\n        order by coalesce(\n          case\n            when regexp_extract(FileNM, '\\\\.D(\\\\d)\\\\.', 1) != ''\n            then try_to_date(\n              concat(\n                '20', substr(regexp_extract(FileNM, '\\\\.D(\\\\d)\\\\.', 1), 1, 2),\n                '-',\n                substr(regexp_extract(FileNM, '\\\\.D(\\\\d)\\\\.', 1), 3, 2),\n                '-',\n                '01'\n              ),\n              'yyyy-MM-dd'\n            )\n            else null\n          end,\n          date_trunc('month', meta_file_dt)\n        ) asc\n      ) as rn_first,\n      row_number() over (\n        partition by MBI_ID\n        order by coalesce(\n          case\n            when regexp_extract(FileNM, '\\\\.D(\\\\d)\\\\.', 1) != ''\n            then try_to_date(\n              concat(\n                '20', substr(regexp_extract(FileNM, '\\\\.D(\\\\d)\\\\.', 1), 1, 2),\n                '-',\n                substr(regexp_extract(FileNM, '\\\\.D(\\\\d)\\\\.', 1), 3, 2),\n                '-',\n                '01'\n              ),\n              'yyyy-MM-dd'\n            )\n            else null\n          end,\n          date_trunc('month', meta_file_dt)\n        ) desc\n      ) as rn_latest\n    from prd_bronze.reach_ingested.provider_alignment_report_r2history\n  ),\n  pbvar_agg as (\n    select\n      MBI_ID,\n      array_join(collect_list(distinct ALGN_TYPE_CLM), '; ') as algn_type_clm,\n      array_join(collect_list(distinct ALGN_TYPE_VA), '; ') as algn_type_va,\n      array_join(collect_list(distinct PRVDR_TIN_NUM_CLM_OR_VA), '; ') as pbvar_prvdr_tins,\n      array_join(collect_list(distinct PRVDR_NPI_NUM_CLM_OR_VA), '; ') as pbvar_prvdr_npis,\n      max(case when rn_first = 1 then PRVDR_NPI_NUM_CLM_OR_VA end) as first_aligned_npi,\n      max(case when rn_first = 1 then PRVDR_TIN_NUM_CLM_OR_VA end) as first_aligned_tin,\n      max(case when rn_first = 1 then file_date_parsed end) as first_alignment_date,\n      max(case when rn_latest = 1 then PRVDR_NPI_NUM_CLM_OR_VA end) as latest_aligned_npi,\n      max(case when rn_latest = 1 then PRVDR_TIN_NUM_CLM_OR_VA end) as latest_aligned_tin,\n      max(case when rn_latest = 1 then file_date_parsed end) as latest_alignment_date,\n      count(distinct PRVDR_NPI_NUM_CLM_OR_VA) as provider_change_count,\n      count(*) as pbvar_record_count\n    from pbvar_raw\n    group by MBI_ID\n  ),\n-- Continue with the rest of your logic unchanged,\n  svar_parsed as (\n    select\n      BeneficiaryMBIID,\n      ResponseCodeList,\n      PractitionerName,\n      PractitionerNPI,\n      PractitionerTIN,\n      SignatureDate,\n      coalesce(\n        try_to_date(trim(SignatureDate), 'yyyy-MM-dd'),\n        try_to_date(trim(SignatureDate), 'MM/dd/yyyy'),\n        try_to_date(trim(SignatureDate), 'M/d/yyyy'),\n        try_to_date(trim(SignatureDate), 'ddMMMyyyy'),\n        try_to_date(upper(trim(SignatureDate)), 'ddMMMyyyy')\n      ) as signature_date_parsed,\n      case\n        when ResponseCodeList rlike 'A[01]' then true\n        else false\n      end as is_valid_response,\n      case\n        when ResponseCodeList = '00' then true\n        else false\n      end as is_pending_cms\n    from prd_bronze.reach_ingested.signed_voluntary_alignment_response_r2history\n  ),\n  svar_latest_all as (\n    select distinct\n      BeneficiaryMBIID,\n      first_value(PractitionerNPI) over (\n        partition by BeneficiaryMBIID\n        order by\n          is_valid_response desc,\n          case when signature_date_parsed is not null then 1 else 0 end desc,\n          signature_date_parsed desc nulls last,\n          ResponseCodeList desc\n      ) as latest_practitioner_npi,\n      first_value(PractitionerTIN) over (\n        partition by BeneficiaryMBIID\n        order by\n          is_valid_response desc,\n          case when signature_date_parsed is not null then 1 else 0 end desc,\n          signature_date_parsed desc nulls last,\n          ResponseCodeList desc\n      ) as latest_practitioner_tin,\n      first_value(PractitionerName) over (\n        partition by BeneficiaryMBIID\n        order by\n          is_valid_response desc,\n          case when signature_date_parsed is not null then 1 else 0 end desc,\n          signature_date_parsed desc nulls last,\n          ResponseCodeList desc\n      ) as latest_practitioner_name\n    from svar_parsed\n  ),\n  svar_latest as (\n    select distinct\n      BeneficiaryMBIID,\n      first_value(ResponseCodeList) over (\n        partition by BeneficiaryMBIID\n        order by signature_date_parsed desc nulls last\n      ) as latest_response_code,\n      first_value(signature_date_parsed) over (\n        partition by BeneficiaryMBIID\n        order by signature_date_parsed desc nulls last\n      ) as latest_response_code_dt\n    from svar_parsed\n    where signature_date_parsed is not null\n  ),\n  svar_latest_valid as (\n    select distinct\n      BeneficiaryMBIID,\n      first_value(ResponseCodeList) over (\n        partition by BeneficiaryMBIID\n        order by signature_date_parsed desc nulls last\n      ) as latest_valid_response_code,\n      first_value(signature_date_parsed) over (\n        partition by BeneficiaryMBIID\n        order by signature_date_parsed desc nulls last\n      ) as latest_valid_response_code_dt\n    from svar_parsed\n    where is_valid_response = true\n      and signature_date_parsed is not null\n  ),\n  svar_agg as (\n    select\n      s.BeneficiaryMBIID,\n      array_join(collect_list(s.ResponseCodeList), '; ') as response_codes,\n      array_join(collect_list(s.PractitionerName), '; ') as practitioner_names,\n      array_join(collect_list(s.PractitionerNPI), '; ') as practitioner_npis,\n      array_join(collect_list(s.PractitionerTIN), '; ') as practitioner_tins,\n      min(s.signature_date_parsed) as first_sva_date,\n      max(s.signature_date_parsed) as latest_sva_date,\n      array_join(collect_list(s.SignatureDate), '; ') as signature_dates,\n      count(*) as sva_signature_count,\n      max(case when s.is_pending_cms then 1 else 0 end) as sva_pending_cms\n    from svar_parsed s\n    group by s.BeneficiaryMBIID\n  ),\n  valid_providers as (\n    select distinct\n      individual_npi as provider_npi,\n      base_provider_tin as provider_tin\n    from uat_sandbox.gov_programs.participant_list\n    where individual_npi is not null\n      and cast(regexp_replace(performance_year, 'PY', '') as int) = year(current_date())\n      and provider_type = 'Individual Provider'\n      and provider_class = 'Participant Provider'\n  ),\n  util_cost as (\n    select\n      hcmpi,\n      ED_visit_90DAYS,\n      ED_visit_180DAYS,\n      ED_visit_365DAYS,\n      SNF_episodes_90DAYS,\n      SNF_episodes_180DAYS,\n      SNF_episodes_365DAYS,\n      admits_90DAYS,\n      admits_180DAYS,\n      admits_365DAYS,\n      obs_90DAYS,\n      obs_180DAYS,\n      obs_365DAYS,\n      ED_visit_YTD,\n      admits_YTD,\n      SNF_episodes_YTD,\n      obs_YTD\n    from prd_silver.patient_metrics.patient_registry_util_cost\n  ),\n  -- Get latest yearmo for cost data\n  latest_yearmo as (\n    select\n      max(to_date(cast(Yearmo as string), 'yyyyMM')) as max_yearmo\n    from prd_silver.patient_metrics.allpayer_cost_util_completed\n    where Metric = 'IP_Paid'\n  ),\n  -- Patient cost metrics aggregated from allpayer_cost_util_completed\n  patient_costs as (\n    select\n      a.hcmpi,\n      -- Cost metrics (PMPM - using completed values)\n      sum(case when a.Metric = 'IP_Paid' then a.Completed_Value else 0 end) as IP_Paid_PMPM,\n      sum(case when a.Metric = 'OP_Paid' then a.Completed_Value else 0 end) as OP_Paid_PMPM,\n      sum(case when a.Metric = 'PB_DME_Paid' then a.Completed_Value else 0 end) as PB_DME_Paid_PMPM,\n      sum(case when a.Metric = 'SNF_Paid' then a.Completed_Value else 0 end) as SNF_Paid_PMPM,\n      sum(case when a.Metric = 'HH_Paid' then a.Completed_Value else 0 end) as HH_Paid_PMPM,\n      sum(case when a.Metric = 'HSP_Paid' then a.Completed_Value else 0 end) as HSP_Paid_PMPM,\n      -- Total cost\n      sum(case when a.Metric like '%_Paid' then a.Completed_Value else 0 end) as Total_Paid_PMPM,\n      -- Raw cost values\n      sum(case when a.Metric = 'IP_Paid' then a.Raw_Value else 0 end) as IP_Paid_Total,\n      sum(case when a.Metric = 'OP_Paid' then a.Raw_Value else 0 end) as OP_Paid_Total,\n      sum(case when a.Metric = 'PB_DME_Paid' then a.Raw_Value else 0 end) as PB_DME_Paid_Total,\n      sum(case when a.Metric = 'SNF_Paid' then a.Raw_Value else 0 end) as SNF_Paid_Total,\n      sum(case when a.Metric = 'HH_Paid' then a.Raw_Value else 0 end) as HH_Paid_Total,\n      sum(case when a.Metric = 'HSP_Paid' then a.Raw_Value else 0 end) as HSP_Paid_Total,\n      sum(case when a.Metric like '%_Paid' then a.Raw_Value else 0 end) as Total_Paid_Dollars,\n      -- Risk scores\n      avg(case when a.Metric = 'Prosp_RS_v28_AllSources' then a.Completed_Value else null end) as Prosp_RAF_v28,\n      avg(case when a.Metric = 'Concur_RS_v28_AllSources' then a.Completed_Value else null end) as Concur_RAF_v28,\n      -- Member months\n      sum(case when a.Metric = 'MM' then a.Completed_Value else 0 end) as Member_Months,\n      -- Program info\n      max(a.Program) as Program,\n      max(a.Payer) as Payer\n    from prd_silver.patient_metrics.allpayer_cost_util_completed a\n    cross join latest_yearmo ly\n    where a.hcmpi is not null\n      and to_date(cast(a.Yearmo as string), 'yyyyMM') >= add_months(ly.max_yearmo, -12)  -- Last 12 months\n      and to_date(cast(a.Yearmo as string), 'yyyyMM') <= ly.max_yearmo\n    group by a.hcmpi\n  )\n  select\n    b.YearNBR as bar_year,\n    b.MonthNBR as bar_month,\n    b.MedicareBeneficiaryID,\n    b.hcmpi,\n    b.AlignmentStatusCD,\n    b.BirthDate,\n    c.lc_status_current,\n    c.payer_current,\n    c.office_name,\n    c.first_engagement_dt,\n    c.latest_engagement_dt,\n    v.sva_signature_count,\n    v.first_sva_date,\n    v.latest_sva_date,\n    l.latest_response_code,\n    l.latest_response_code_dt,\n    lv.latest_valid_response_code,\n    lv.latest_valid_response_code_dt,\n    la.latest_practitioner_npi as sva_provider_npi,\n    la.latest_practitioner_tin as sva_provider_tin,\n    la.latest_practitioner_name as sva_provider_name,\n    case\n      when la.latest_practitioner_npi is null or la.latest_practitioner_tin is null then null\n      when vp.provider_npi is not null then true\n      else false\n    end as sva_provider_valid,\n    v.sva_pending_cms,\n    case\n      when lv.latest_valid_response_code_dt is not null\n      then make_date(year(lv.latest_valid_response_code_dt) + 3, 1, 1)\n      else null\n    end as response_code_expiration_dt,\n    case\n      when lv.latest_valid_response_code_dt is not null\n        and make_date(year(lv.latest_valid_response_code_dt) + 3, 1, 1) < current_date()\n      then 1\n      when lv.latest_valid_response_code_dt is not null then 0\n      else null\n    end as response_code_expired_flag,\n    datediff(current_date(), v.latest_sva_date) as days_since_last_sva,\n    v.practitioner_names,\n    v.practitioner_npis,\n    v.practitioner_tins,\n    v.signature_dates,\n    v.response_codes,\n    p.first_aligned_npi,\n    p.first_aligned_tin,\n    p.first_alignment_date,\n    p.latest_aligned_npi,\n    p.latest_aligned_tin,\n    p.latest_alignment_date,\n    p.provider_change_count,\n    p.pbvar_record_count,\n    p.algn_type_clm,\n    p.algn_type_va,\n    p.pbvar_prvdr_tins,\n    p.pbvar_prvdr_npis,\n    case when p.MBI_ID is not null then true else false end as pbvar_aligned,\n    pm.palmr_algn_type_clm,\n    pm.palmr_algn_type_va,\n    pm.palmr_prvdr_tins,\n    pm.palmr_prvdr_npis,\n    pm.palmr_claim_line_count,\n    case\n      when p.MBI_ID is not null then 'Aligned'\n      when v.sva_signature_count > 0 then 'Signed'\n      else 'Not Signed'\n    end as alignment_journey_status,\n    case\n      when v.sva_signature_count = 0 or v.sva_signature_count is null then 'Never Signed'\n      when la.latest_practitioner_npi is not null and la.latest_practitioner_tin is not null\n        and vp.provider_npi is null then 'Invalid Provider'\n      when year(v.latest_sva_date) = year(current_date()) then 'Current Year'\n      when datediff(current_date(), v.latest_sva_date) <= 365 then 'Recent'\n      when datediff(current_date(), v.latest_sva_date) <= 730 then 'Aging'\n      else 'Old'\n    end as signature_status,\n    case\n      when b.hcmpi is null then 'MBI not found in hcmpimaster'\n      when c.hcmpi is null then 'Active in BAR but not in Census'\n      else 'Found in Census'\n    end as status_note,\n    uc.ED_visit_90DAYS,\n    uc.ED_visit_180DAYS,\n    uc.ED_visit_365DAYS,\n    uc.SNF_episodes_90DAYS,\n    uc.SNF_episodes_180DAYS,\n    uc.SNF_episodes_365DAYS,\n    uc.admits_90DAYS,\n    uc.admits_180DAYS,\n    uc.admits_365DAYS,\n    uc.obs_90DAYS,\n    uc.obs_180DAYS,\n    uc.obs_365DAYS,\n    uc.ED_visit_YTD,\n    uc.admits_YTD,\n    uc.SNF_episodes_YTD,\n    uc.obs_YTD,\n    pc.IP_Paid_PMPM,\n    pc.OP_Paid_PMPM,\n    pc.PB_DME_Paid_PMPM,\n    pc.SNF_Paid_PMPM,\n    pc.HH_Paid_PMPM,\n    pc.HSP_Paid_PMPM,\n    pc.Total_Paid_PMPM,\n    pc.IP_Paid_Total,\n    pc.OP_Paid_Total,\n    pc.PB_DME_Paid_Total,\n    pc.SNF_Paid_Total,\n    pc.HH_Paid_Total,\n    pc.HSP_Paid_Total,\n    pc.Total_Paid_Dollars,\n    pc.Prosp_RAF_v28,\n    pc.Concur_RAF_v28,\n    pc.Member_Months,\n    pc.Program,\n    pc.Payer\n  from latest_bar b\n  left join census_data c\n    on b.hcmpi = c.hcmpi\n  left join svar_agg v\n    on b.MedicareBeneficiaryID = v.BeneficiaryMBIID\n  left join svar_latest l\n    on b.MedicareBeneficiaryID = l.BeneficiaryMBIID\n  left join svar_latest_valid lv\n    on b.MedicareBeneficiaryID = lv.BeneficiaryMBIID\n  left join svar_latest_all la\n    on b.MedicareBeneficiaryID = la.BeneficiaryMBIID\n  left join pbvar_agg p\n    on b.MedicareBeneficiaryID = p.MBI_ID\n  left join palmr_agg pm\n    on b.MedicareBeneficiaryID = pm.MBI_ID\n  left join valid_providers vp\n    on la.latest_practitioner_npi = vp.provider_npi\n    and la.latest_practitioner_tin = vp.provider_tin\n  left join util_cost uc\n    on b.hcmpi = uc.hcmpi\n  left join patient_costs pc\n    on b.hcmpi = pc.hcmpi\n),\n-- Calculate power ranking score based on utilization metrics\npatient_scores as (\n  select\n    base_alignment.*,\n    -- Weighted composite score prioritizing recent high-acuity utilization\n    -- Weights: 90-day (3x), 180-day (2x), 365-day (1x), YTD (0.5x)\n    -- Higher weights for acute events: Admits (4x), SNF (3x), ED (2x), Obs (1x)\n    (\n      -- Admits scoring (highest priority - inpatient stays)\n      coalesce(base_alignment.admits_90DAYS, 0) * 12.0 +     -- 90-day admits: 4 * 3 = 12\n      coalesce(base_alignment.admits_180DAYS, 0) * 8.0 +     -- 180-day admits: 4 * 2 = 8\n      coalesce(base_alignment.admits_365DAYS, 0) * 4.0 +     -- 365-day admits: 4 * 1 = 4\n      coalesce(base_alignment.admits_YTD, 0) * 2.0 +         -- YTD admits: 4 * 0.5 = 2\n\n      -- SNF episodes scoring (second priority - post-acute care)\n      coalesce(base_alignment.SNF_episodes_90DAYS, 0) * 9.0 +   -- 90-day SNF: 3 * 3 = 9\n      coalesce(base_alignment.SNF_episodes_180DAYS, 0) * 6.0 +  -- 180-day SNF: 3 * 2 = 6\n      coalesce(base_alignment.SNF_episodes_365DAYS, 0) * 3.0 +  -- 365-day SNF: 3 * 1 = 3\n      coalesce(base_alignment.SNF_episodes_YTD, 0) * 1.5 +      -- YTD SNF: 3 * 0.5 = 1.5\n\n      -- ED visits scoring (third priority - emergency care)\n      coalesce(base_alignment.ED_visit_90DAYS, 0) * 6.0 +    -- 90-day ED: 2 * 3 = 6\n      coalesce(base_alignment.ED_visit_180DAYS, 0) * 4.0 +   -- 180-day ED: 2 * 2 = 4\n      coalesce(base_alignment.ED_visit_365DAYS, 0) * 2.0 +   -- 365-day ED: 2 * 1 = 2\n      coalesce(base_alignment.ED_visit_YTD, 0) * 1.0 +       -- YTD ED: 2 * 0.5 = 1\n\n      -- Observation stays scoring (lowest priority)\n      coalesce(base_alignment.obs_90DAYS, 0) * 3.0 +         -- 90-day obs: 1 * 3 = 3\n      coalesce(base_alignment.obs_180DAYS, 0) * 2.0 +        -- 180-day obs: 1 * 2 = 2\n      coalesce(base_alignment.obs_365DAYS, 0) * 1.0 +        -- 365-day obs: 1 * 1 = 1\n      coalesce(base_alignment.obs_YTD, 0) * 0.5              -- YTD obs: 1 * 0.5 = 0.5\n    ) as power_score,\n\n    -- Additional derived metrics for context\n    coalesce(base_alignment.admits_90DAYS, 0) +\n      coalesce(base_alignment.SNF_episodes_90DAYS, 0) +\n      coalesce(base_alignment.ED_visit_90DAYS, 0) +\n      coalesce(base_alignment.obs_90DAYS, 0) as total_events_90days,\n\n    coalesce(base_alignment.admits_365DAYS, 0) +\n      coalesce(base_alignment.SNF_episodes_365DAYS, 0) +\n      coalesce(base_alignment.ED_visit_365DAYS, 0) +\n      coalesce(base_alignment.obs_365DAYS, 0) as total_events_365days\n  from base_alignment\n  where base_alignment.latest_aligned_npi is not null  -- Only include patients with an aligned provider\n),\n-- Rank patients within each provider's panel\nprovider_rankings as (\n  select\n    *,\n    row_number() over (\n      partition by latest_aligned_npi\n      order by power_score desc, total_events_90days desc, MedicareBeneficiaryID\n    ) as provider_rank,\n    count(*) over (partition by latest_aligned_npi) as provider_panel_size,\n    avg(power_score) over (partition by latest_aligned_npi) as provider_avg_score,\n    max(power_score) over (partition by latest_aligned_npi) as provider_max_score\n  from patient_scores\n)\nselect\n  -- Provider information\n  latest_aligned_npi,\n  latest_aligned_tin,\n  provider_rank,\n  provider_panel_size,\n  round(provider_avg_score, 2) as provider_avg_score,\n  round(provider_max_score, 2) as provider_max_score,\n\n  -- Patient identifiers\n  MedicareBeneficiaryID,\n  hcmpi,\n\n  -- Power ranking metrics\n  round(power_score, 2) as power_score,\n  total_events_90days,\n  total_events_365days,\n\n  -- Patient demographics and status\n  BirthDate,\n  lc_status_current,\n  payer_current,\n  office_name,\n  alignment_journey_status,\n  signature_status,\n\n  -- Recent utilization (90-day)\n  admits_90DAYS,\n  SNF_episodes_90DAYS,\n  ED_visit_90DAYS,\n  obs_90DAYS,\n\n  -- Medium-term utilization (180-day)\n  admits_180DAYS,\n  SNF_episodes_180DAYS,\n  ED_visit_180DAYS,\n  obs_180DAYS,\n\n  -- Long-term utilization (365-day)\n  admits_365DAYS,\n  SNF_episodes_365DAYS,\n  ED_visit_365DAYS,\n  obs_365DAYS,\n\n  -- YTD utilization\n  admits_YTD,\n  SNF_episodes_YTD,\n  ED_visit_YTD,\n  obs_YTD,\n\n  -- Cost metrics (PMPM - last 12 months)\n  round(IP_Paid_PMPM, 2) as IP_Paid_PMPM,\n  round(OP_Paid_PMPM, 2) as OP_Paid_PMPM,\n  round(PB_DME_Paid_PMPM, 2) as PB_DME_Paid_PMPM,\n  round(SNF_Paid_PMPM, 2) as SNF_Paid_PMPM,\n  round(HH_Paid_PMPM, 2) as HH_Paid_PMPM,\n  round(HSP_Paid_PMPM, 2) as HSP_Paid_PMPM,\n  round(Total_Paid_PMPM, 2) as Total_Paid_PMPM,\n\n  -- Total cost dollars (last 12 months)\n  round(IP_Paid_Total, 2) as IP_Paid_Total,\n  round(OP_Paid_Total, 2) as OP_Paid_Total,\n  round(PB_DME_Paid_Total, 2) as PB_DME_Paid_Total,\n  round(SNF_Paid_Total, 2) as SNF_Paid_Total,\n  round(HH_Paid_Total, 2) as HH_Paid_Total,\n  round(HSP_Paid_Total, 2) as HSP_Paid_Total,\n  round(Total_Paid_Dollars, 2) as Total_Paid_Dollars,\n\n  -- Risk scores\n  round(Prosp_RAF_v28, 3) as Prosp_RAF_v28,\n  round(Concur_RAF_v28, 3) as Concur_RAF_v28,\n\n  -- Member months and program\n  round(Member_Months, 1) as Member_Months,\n  Program,\n  Payer,\n\n  -- Alignment details\n  first_alignment_date,\n  latest_alignment_date,\n  provider_change_count,\n\n  -- SVA information\n  sva_signature_count,\n  latest_sva_date,\n  sva_provider_npi,\n  sva_provider_name,\n\n  -- Census details\n  first_engagement_dt,\n  latest_engagement_dt,\n\n  -- Additional context\n  bar_year,\n  bar_month,\n  status_note\n\nfrom provider_rankings\nwhere provider_rank <= 30  -- Top 30 patients per provider\norder by\n  latest_aligned_npi,\n  provider_rank\n"
